INSERT INTO public.challenges (id, title, topic, difficulty, xp_reward, problem_statement, created_at) OVERRIDING SYSTEM VALUE VALUES (1, 'Find the Largest Element', 'Arrays', 'Easy', 20, 'Read n integers and print the largest value.', '2026-11-10 17:33:28.772686+05:30');
INSERT INTO public.challenges (id, title, topic, difficulty, xp_reward, problem_statement, created_at) OVERRIDING SYSTEM VALUE VALUES (2, 'Find the Second Largest Element', 'Arrays', 'Easy', 20, 'Given an array of n integers, print the second-largest distinct value. If no second-largest distinct value exists, print -1.', '2026-11-11 23:07:25.997542+05:30');
INSERT INTO public.challenges (id, title, topic, difficulty, xp_reward, problem_statement, created_at) OVERRIDING SYSTEM VALUE VALUES (3, 'Reverse an Array', 'Arrays', 'Easy', 20, 'Given n integers, print them in reverse order. The first input is n, followed by n space-separated integers. Print the reversed integers separated by spaces.', '2026-11-13 16:57:23.254496+05:30');
INSERT INTO public.challenges (id, title, topic, difficulty, xp_reward, problem_statement, created_at) OVERRIDING SYSTEM VALUE VALUES (4, 'Check if Array Is Sorted', 'Arrays', 'Easy', 20, 'Given n integers, determine whether they are sorted in non-decreasing order. The first input is n, followed by n space-separated integers. Print YES if the array is sorted; otherwise, print NO.', '2026-11-13 17:37:00.799311+05:30');
INSERT INTO public.challenges (id, title, topic, difficulty, xp_reward, problem_statement, created_at) OVERRIDING SYSTEM VALUE VALUES (5, 'Move Zeroes to End', 'Arrays', 'Easy', 20, 'Given n integers, move all zeroes to the end while keeping the order of the non-zero elements unchanged. The input contains n followed by n space-separated integers. Print the resulting array.', '2026-11-13 17:44:10.684314+05:30');
INSERT INTO public.challenges (id, title, topic, difficulty, xp_reward, problem_statement, created_at) OVERRIDING SYSTEM VALUE VALUES (6, 'Remove Duplicates from Sorted Array', 'Arrays', 'Easy', 20, 'Given a sorted array of n integers, remove duplicates so that each distinct value appears once. Print the remaining values in their original order, separated by spaces. The input contains n followed by n sorted integers.', '2026-11-13 17:45:57.1475+05:30');
INSERT INTO public.challenges (id, title, topic, difficulty, xp_reward, problem_statement, created_at) OVERRIDING SYSTEM VALUE VALUES (7, 'Merge Two Sorted Arrays', 'Arrays', 'Easy', 20, 'Given two sorted arrays of integers, merge them into one sorted array. The first input line contains n and m, the sizes of the arrays. The next n integers are the first array, followed by m integers for the second array. Print all n + m values in sorted order, separated by spaces.', '2026-11-13 17:48:00.833161+05:30');
INSERT INTO public.challenges (id, title, topic, difficulty, xp_reward, problem_statement, created_at) OVERRIDING SYSTEM VALUE VALUES (8, 'Left Rotate Array by One', 'Arrays', 'Easy', 20, 'Given n integers, perform a left rotation by one position. The first element moves to the end, and every other element shifts one position left. The input contains n followed by n space-separated integers. Print the rotated array separated by spaces.', '2026-11-13 17:49:18.672428+05:30');
INSERT INTO public.challenges (id, title, topic, difficulty, xp_reward, problem_statement, created_at) OVERRIDING SYSTEM VALUE VALUES (9, 'Find the Missing Number', 'Arrays', 'Easy', 20, 'An array contains n distinct integers from the range 0 to n, with exactly one number missing. The input contains n followed by n space-separated integers. Print the missing number.', '2026-11-13 17:50:04.242435+05:30');
INSERT INTO public.challenges (id, title, topic, difficulty, xp_reward, problem_statement, created_at) OVERRIDING SYSTEM VALUE VALUES (10, 'Maximum Consecutive Ones', 'Arrays', 'Easy', 20, 'Given an array containing only 0s and 1s, find the maximum number of consecutive 1s. The input contains n followed by n space-separated values. Print the maximum count.', '2026-11-13 17:50:51.618103+05:30');
INSERT INTO public.challenges (id, title, topic, difficulty, xp_reward, problem_statement, created_at) OVERRIDING SYSTEM VALUE VALUES (11, 'Two Sum', 'Arrays', 'Medium', 40, 'Given n integers and a target value, find the two distinct 0-based indices i and j (i < j) whose values add up to the target. Exactly one valid pair exists. The input contains n, then n space-separated integers, then the target. Print i and j.', '2026-11-13 20:37:53.499537+05:30');
INSERT INTO public.challenges (id, title, topic, difficulty, xp_reward, problem_statement, created_at) OVERRIDING SYSTEM VALUE VALUES (12, 'Best Time to Buy and Sell Stock', 'Arrays', 'Easy', 20, 'Given n daily stock prices, choose one day to buy and a later day to sell to maximize profit. If no positive profit is possible, print 0. The input contains n followed by n space-separated prices. Print the maximum profit.', '2026-11-13 20:40:14.044798+05:30');
INSERT INTO public.challenges (id, title, topic, difficulty, xp_reward, problem_statement, created_at) OVERRIDING SYSTEM VALUE VALUES (13, 'Find the Majority Element', 'Arrays', 'Easy', 20, 'Given an array of n integers, find the value that appears more than floor(n / 2) times. It is guaranteed that such a value exists. The input contains n followed by n space-separated integers. Print the majority element.', '2026-11-13 20:41:15.881957+05:30');
INSERT INTO public.challenges (id, title, topic, difficulty, xp_reward, problem_statement, created_at) OVERRIDING SYSTEM VALUE VALUES (14, 'Leaders in an Array', 'Arrays', 'Easy', 20, 'An element is a leader if it is strictly greater than every element to its right. The last element is always a leader. Given n integers, print all leaders in their original order, separated by spaces. The input contains n followed by n space-separated integers.', '2026-11-13 20:52:01.974758+05:30');
INSERT INTO public.challenges (id, title, topic, difficulty, xp_reward, problem_statement, created_at) OVERRIDING SYSTEM VALUE VALUES (15, 'Union of Two Sorted Arrays', 'Arrays', 'Easy', 20, 'Given two sorted arrays, print their union: every distinct value that appears in either array, in ascending order. The first input line contains n and m, followed by n sorted integers for the first array and m sorted integers for the second array. Print each union value once, separated by spaces.', '2026-11-13 20:52:51.950543+05:30');
INSERT INTO public.challenges (id, title, topic, difficulty, xp_reward, problem_statement, created_at) OVERRIDING SYSTEM VALUE VALUES (16, 'Longest Subarray with Sum K', 'Arrays', 'Easy', 20, 'Given an array of n positive integers and a target k, find the length of the longest contiguous subarray whose sum is exactly k. If no such subarray exists, print 0. The first input line contains n and k, followed by n positive integers. Print the length.', '2026-11-13 20:54:02.004583+05:30');
INSERT INTO public.challenges (id, title, topic, difficulty, xp_reward, problem_statement, created_at) OVERRIDING SYSTEM VALUE VALUES (17, 'Product of Array Except Self', 'Arrays', 'Medium', 40, 'Given an array of n integers, print an output array where each position contains the product of all input values except the value at that position. Do not use division. The input contains n followed by n space-separated integers. Print n space-separated products. All products fit in a 64-bit signed integer.', '2026-11-13 21:02:29.336258+05:30');
INSERT INTO public.challenges (id, title, topic, difficulty, xp_reward, problem_statement, created_at) OVERRIDING SYSTEM VALUE VALUES (18, 'Maximum Subarray Sum', 'Arrays', 'Medium', 40, 'Given n integers, which may be positive, zero, or negative, find the maximum sum of any non-empty contiguous subarray. The input contains n followed by n space-separated integers. Print the maximum sum. The result fits in a 64-bit signed integer.', '2026-11-13 21:27:45.138279+05:30');
INSERT INTO public.challenges (id, title, topic, difficulty, xp_reward, problem_statement, created_at) OVERRIDING SYSTEM VALUE VALUES (19, 'Sort Colors', 'Arrays', 'Medium', 40, 'Given an array containing only 0s, 1s, and 2s, sort it in ascending order without using a built-in sorting function. The input contains n followed by n space-separated values. Print the sorted array separated by spaces.', '2026-11-13 21:28:48.096085+05:30');
INSERT INTO public.challenges (id, title, topic, difficulty, xp_reward, problem_statement, created_at) OVERRIDING SYSTEM VALUE VALUES (20, 'Container With Most Water', 'Arrays', 'Medium', 40, 'Given n non-negative heights, choose two different positions i and j (i < j) to form a container. Its area is min(height[i], height[j]) * (j - i). Print the maximum possible area. The input contains n followed by n space-separated heights. The result fits in a 64-bit signed integer.', '2026-11-13 21:29:53.035266+05:30');
INSERT INTO public.challenges (id, title, topic, difficulty, xp_reward, problem_statement, created_at) OVERRIDING SYSTEM VALUE VALUES (21, '3Sum', 'Arrays', 'Medium', 40, 'Given n integers, find all unique triplets of values from three distinct indices whose sum is 0. Print each triplet on its own line with its values in ascending order. Print the triplets in lexicographic order. If no triplet exists, print -1. The input contains n followed by n space-separated integers.', '2026-11-13 21:30:51.55185+05:30');
INSERT INTO public.challenges (id, title, topic, difficulty, xp_reward, problem_statement, created_at) OVERRIDING SYSTEM VALUE VALUES (22, 'Subarray Sum Equals K', 'Arrays', 'Medium', 40, 'Given an array of n integers, which may include negative values, and a target k, count the contiguous subarrays whose sum is exactly k. The first input line contains n and k, followed by n space-separated integers. Print the count. The count fits in a 64-bit signed integer.', '2026-11-13 21:31:39.232404+05:30');
INSERT INTO public.challenges (id, title, topic, difficulty, xp_reward, problem_statement, created_at) OVERRIDING SYSTEM VALUE VALUES (23, 'Longest Consecutive Sequence', 'Arrays', 'Medium', 40, 'Given an unsorted array of n integers, find the length of the longest sequence of consecutive values. The values do not need to be adjacent in the array, and duplicates do not increase the sequence length. The input contains n followed by n space-separated integers. Print the length.', '2026-11-13 21:32:30.104931+05:30');
INSERT INTO public.challenges (id, title, topic, difficulty, xp_reward, problem_statement, created_at) OVERRIDING SYSTEM VALUE VALUES (24, 'Rotate Array by K', 'Arrays', 'Medium', 40, 'Given an array of n integers and a non-negative integer k, rotate the array to the right by k positions. If k is greater than n, use k modulo n. The first input line contains n and k, followed by n space-separated integers. Print the rotated array separated by spaces.', '2026-11-13 21:33:23.601584+05:30');
INSERT INTO public.challenges (id, title, topic, difficulty, xp_reward, problem_statement, created_at) OVERRIDING SYSTEM VALUE VALUES (25, 'Next Permutation', 'Arrays', 'Medium', 40, 'Given n integers representing a permutation, rearrange them into the lexicographically next greater permutation. If no greater arrangement exists, rearrange the values into ascending order. Repeated values are allowed. The input contains n followed by n space-separated integers. Print the resulting permutation separated by spaces.', '2026-11-13 21:34:16.438225+05:30');
