INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (1, 1, 'Beginner', 'mcq', 'Which header is needed to use std::cout?', '{"options": ["<iostream>", "<string>", "<vector>", "<cmath>"]}', '"<iostream>"', 'The iostream header provides standard input and output tools such as std::cout.', 5, 1, true, '2026-11-14 19:01:07.30822+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (2, 1, 'Intermediate', 'code_output', 'What does this program print?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int result = 1;\n    for (int i = 1; i <= 3; i++) {\n        if (i % 2 == 1) result += i;\n        else result *= i;\n    }\n    cout << result;\n    return 0;\n}", "options": ["6", "7", "8", "9"]}', '"7"', 'Trace each loop: result starts at 1. At i=1, add 1 to get 2. At i=2, multiply by 2 to get 4. At i=3, add 3 to get 7.', 10, 1, true, '2026-11-14 19:01:07.30822+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (3, 1, 'Advanced', 'code_output', 'What does this program print?', '{"code": "#include <iostream>\nusing namespace std;\n\nvoid update(int& first, int second) {\n    first += second;\n    second += first;\n}\n\nint main() {\n    int a = 2, b = 3;\n    update(a, b);\n    cout << a << \" \" << b;\n    return 0;\n}", "options": ["5 3", "5 8", "2 3", "8 3"]}', '"5 3"', 'first is a reference to a, so a becomes 5. second is a copy of b, so changing second does not change b. Output: 5 3.', 15, 1, true, '2026-11-14 19:01:07.30822+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (4, 1, 'Beginner', 'mcq', 'What is the role of main() in a C++ program?', '{"options": ["It is the program entry point", "It includes a header file", "It creates a loop", "It declares every variable"]}', '"It is the program entry point"', 'Execution of a standard C++ program begins in the main() function.', 5, 2, true, '2026-11-15 22:58:17.048385+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (5, 1, 'Beginner', 'mcq', 'Which statement prints Hello and then starts a new line?', '{"options": ["cout << \"Hello\";", "cout << \"Hello\" << endl;", "cin >> \"Hello\";", "print(\"Hello\");"]}', '"cout << \"Hello\" << endl;"', 'cout sends text to the output stream. endl also starts a new line.', 5, 3, true, '2026-11-15 22:58:17.048385+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (6, 1, 'Beginner', 'mcq', 'Which symbol usually ends a C++ statement?', '{"options": [":", ";", "{}", "#"]}', '";"', 'A semicolon marks the end of most C++ statements.', 5, 4, true, '2026-11-15 22:58:17.048385+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (7, 1, 'Intermediate', 'code_output', 'After the loop finishes, what value does sum contain?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int sum = 0;\n    for (int i = 1; i <= 5; i++) {\n        if (i % 2 == 0) continue;\n        sum += i * i;\n    }\n    cout << sum;\n    return 0;\n}", "options": ["25", "30", "35", "55"]}', '"35"', 'Even values are skipped. The program adds 1×1, 3×3, and 5×5, giving 35.', 10, 5, true, '2026-11-15 23:02:59.367217+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (8, 1, 'Intermediate', 'code_output', 'What value is printed after the loop?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int value = 2;\n    for (int i = 1; i <= 3; i++) {\n        value += i;\n        if (value > 4) value -= 2;\n    }\n    cout << value;\n    return 0;\n}", "options": ["3", "4", "5", "6"]}', '"4"', 'Trace value through the loop: 2 → 3 → 5 → 3 → 6 → 4.', 10, 6, true, '2026-11-15 23:02:59.367217+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (9, 1, 'Advanced', 'code_output', 'What number is printed after both calls to process?', '{"code": "#include <iostream>\nusing namespace std;\nint process(int x) {\n    if (x < 5) return x + 2;\n    return x / 2;\n}\nint main() {\n    int value = process(3);\n    value = process(value);\n    cout << value;\n    return 0;\n}", "options": ["2", "3", "5", "7"]}', '"2"', 'process(3) returns 5. Then process(5) returns 5 / 2, which is 2 with integer division.', 15, 7, true, '2026-11-15 23:04:35.024389+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (10, 1, 'Advanced', 'code_output', 'What value does calculate(5) print?', '{"code": "#include <iostream>\nusing namespace std;\nint calculate(int n) {\n    int total = 0;\n    for (int i = 1; i <= n; i++) {\n        if (i % 2 == 0) total += i;\n        else total -= i;\n    }\n    return total;\n}\nint main() {\n    cout << calculate(5);\n    return 0;\n}", "options": ["-3", "-1", "3", "5"]}', '"-3"', 'The total becomes -1 + 2 - 3 + 4 - 5, which equals -3.', 15, 8, true, '2026-11-15 23:04:35.024389+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (11, 2, 'Beginner', 'mcq', 'Which declaration creates an integer variable named score with value 42?', '{"options": ["int score = 42;", "double score = 42;", "char score = 42;", "bool score = 42;"]}', '"int score = 42;"', 'int is the usual C++ type for whole-number values.', 5, 1, true, '2026-11-15 23:05:38.941527+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (12, 2, 'Beginner', 'code_output', 'What value is printed after the assignment?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int count = 8;\n    count += 4;\n    cout << count;\n    return 0;\n}", "options": ["4", "8", "12", "84"]}', '"12"', 'count += 4 adds 4 to the original value 8, so count becomes 12.', 5, 2, true, '2026-11-15 23:05:38.941527+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (13, 2, 'Beginner', 'code_output', 'What does this program print?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    double price = 12.5;\n    int quantity = 2;\n    cout << price * quantity;\n    return 0;\n}", "options": ["14.5", "24", "25", "12.5"]}', '"25"', '12.5 multiplied by 2 equals 25.', 5, 3, true, '2026-11-15 23:05:38.941527+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (14, 2, 'Beginner', 'code_output', 'Which character does this program print?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    char grade = ''P'';\n    cout << grade;\n    return 0;\n}", "options": ["P", "grade", "0", "Compilation error"]}', '"P"', 'The char variable grade stores the single character P.', 5, 4, true, '2026-11-15 23:05:38.941527+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (15, 2, 'Intermediate', 'code_output', 'What does this program print? Pay attention to integer division.', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int whole = 5;\n    double value = whole / 2;\n    cout << value;\n    return 0;\n}", "options": ["2", "2.5", "3", "5"]}', '"2"', 'Both operands of whole / 2 are integers, so division gives 2 before the result is stored in value.', 10, 5, true, '2026-11-15 23:08:26.506197+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (16, 2, 'Intermediate', 'code_output', 'What value does the program print after the inner block ends?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int score = 7;\n    {\n        int score = 3;\n        score += 2;\n    }\n    cout << score;\n    return 0;\n}", "options": ["3", "5", "7", "9"]}', '"7"', 'The inner score is a separate variable. After its block ends, the outer score is still 7.', 10, 6, true, '2026-11-15 23:08:26.506197+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (17, 2, 'Intermediate', 'code_output', 'What pair of values does this program print?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int a = 4, b = 3;\n    a += b * 2;\n    b += a / 2;\n    cout << a << \" \" << b;\n    return 0;\n}", "options": ["10 8", "10 5", "14 10", "8 7"]}', '"10 8"', 'First a becomes 4 + 3×2 = 10. Then b becomes 3 + 10/2 = 8.', 10, 7, true, '2026-11-15 23:08:26.506197+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (18, 2, 'Advanced', 'code_output', 'What value is printed after assigning price to an integer?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    double price = 19.8;\n    int wholePrice = price;\n    cout << wholePrice;\n    return 0;\n}", "options": ["19", "20", "19.8", "Compilation error"]}', '"19"', 'Assigning a double to an int discards the fractional part, so wholePrice becomes 19.', 15, 8, true, '2026-11-15 23:09:16.577835+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (19, 2, 'Advanced', 'find_error', 'What happens when this program is compiled?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    const int attempts = 3;\n    attempts += 1;\n    cout << attempts;\n    return 0;\n}", "options": ["It prints 3", "It prints 4", "Compilation error", "It prints 0"]}', '"Compilation error"', 'A const variable cannot be changed after it has been initialized.', 15, 9, true, '2026-11-15 23:09:16.577835+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (20, 2, 'Advanced', 'code_output', 'What value does half contain?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int count = 7;\n    double half = static_cast<double>(count) / 2;\n    cout << half;\n    return 0;\n}", "options": ["3", "3.5", "4", "7"]}', '"3.5"', 'The cast converts count to double before division, so 7 / 2 becomes 3.5.', 15, 10, true, '2026-11-15 23:09:16.577835+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (21, 3, 'Beginner', 'code_output', 'What value does this expression produce?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int result = 10 - 3 * 2;\n    cout << result;\n    return 0;\n}", "options": ["4", "14", "7", "20"]}', '"4"', 'Multiplication happens before subtraction: 10 - (3 × 2) = 4.', 5, 1, true, '2026-11-15 23:09:58.275337+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (22, 3, 'Beginner', 'code_output', 'What does this program print when age is 18?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int age = 18;\n    cout << (age >= 18);\n    return 0;\n}", "options": ["0", "1", "18", "true"]}', '"1"', 'The comparison is true. C++ prints true as 1 by default.', 5, 2, true, '2026-11-15 23:09:58.275337+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (23, 3, 'Beginner', 'code_output', 'What is the final value of score?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int score = 5;\n    score += 3;\n    cout << score;\n    return 0;\n}", "options": ["2", "5", "8", "15"]}', '"8"', 'score += 3 adds 3 to the original value 5.', 5, 3, true, '2026-11-15 23:09:58.275337+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (24, 3, 'Beginner', 'code_output', 'What remainder does this program print?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int remainder = 17 % 5;\n    cout << remainder;\n    return 0;\n}", "options": ["2", "3", "5", "12"]}', '"2"', '17 divided by 5 leaves a remainder of 2.', 5, 4, true, '2026-11-15 23:09:58.275337+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (25, 3, 'Intermediate', 'code_output', 'What value is added to total by this loop?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int total = 0;\n    for (int i = 1; i <= 6; i++) {\n        if (i % 2 == 0 || i % 3 == 0) total += i;\n    }\n    cout << total;\n    return 0;\n}", "options": ["12", "15", "21", "24"]}', '"15"', 'The values satisfying the condition are 2, 3, 4, and 6. Their sum is 15.', 10, 5, true, '2026-11-15 23:10:41.255476+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (26, 3, 'Intermediate', 'code_output', 'What three values does this program print?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int x = 4;\n    int y = x++;\n    int z = ++x;\n    cout << x << \" \" << y << \" \" << z;\n    return 0;\n}", "options": ["6 4 6", "6 5 6", "5 4 5", "5 5 6"]}', '"6 4 6"', 'y gets the old x value 4, then x becomes 5. The prefix increment raises x to 6, which is assigned to z.', 10, 6, true, '2026-11-15 23:10:41.255476+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (27, 3, 'Intermediate', 'code_output', 'What does this program print? Consider the short-circuit operator.', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int a = 2, b = 3;\n    bool result = (a++ > 2) && (++b > 3);\n    cout << a << \" \" << b << \" \" << result;\n    return 0;\n}", "options": ["3 4 0", "3 3 0", "2 4 1", "3 4 1"]}', '"3 3 0"', 'a++ makes a become 3, but its old value 2 makes the left condition false. && then skips the right side, so b stays 3. result is false, printed as 0.', 10, 7, true, '2026-11-15 23:10:41.255476+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (28, 3, 'Advanced', 'code_output', 'What three values do the bitwise operations print?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int a = 6, b = 3;\n    cout << (a & b) << \" \" << (a | b) << \" \" << (a ^ b);\n    return 0;\n}", "options": ["2 7 5", "1 7 6", "2 6 5", "3 7 5"]}', '"2 7 5"', 'In binary, 6 is 110 and 3 is 011. AND gives 010 (2), OR gives 111 (7), and XOR gives 101 (5).', 15, 8, true, '2026-11-15 23:11:29.148728+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (29, 3, 'Advanced', 'code_output', 'What value does this program print after the bit shifts?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int value = 3;\n    value = (value << 1) + (8 >> 2);\n    cout << value;\n    return 0;\n}", "options": ["6", "7", "8", "10"]}', '"8"', '3 shifted left by 1 is 6. 8 shifted right by 2 is 2. Their sum is 8.', 15, 9, true, '2026-11-15 23:11:29.148728+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (30, 3, 'Advanced', 'code_output', 'What values are printed by the conditional expression?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int x = 5;\n    int y = x > 3 ? x++ : ++x;\n    cout << x << \" \" << y;\n    return 0;\n}", "options": ["5 5", "6 5", "6 6", "7 6"]}', '"6 5"', 'The condition is true, so x++ is selected. y receives the old value 5, then x becomes 6.', 15, 10, true, '2026-11-15 23:11:29.148728+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (31, 4, 'Beginner', 'code_output', 'What does this program print when temperature is 30?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int temperature = 30;\n    if (temperature > 25) cout << \"Hot\";\n    else cout << \"Cool\";\n    return 0;\n}", "options": ["Hot", "Cool", "30", "Compilation error"]}', '"Hot"', '30 is greater than 25, so the if branch prints Hot.', 5, 1, true, '2026-11-15 23:12:41.844027+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (32, 4, 'Beginner', 'code_output', 'What does this program print when number is 6?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int number = 6;\n    if (number % 2 == 0) cout << \"Even\";\n    else cout << \"Odd\";\n    return 0;\n}", "options": ["Even", "Odd", "6", "Compilation error"]}', '"Even"', '6 % 2 is 0, so the condition is true and the program prints Even.', 5, 2, true, '2026-11-15 23:12:41.844027+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (33, 4, 'Beginner', 'code_output', 'Which grade does the program print for score 75?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int score = 75;\n    if (score >= 90) cout << \"A\";\n    else if (score >= 60) cout << \"B\";\n    else cout << \"C\";\n    return 0;\n}", "options": ["A", "B", "C", "75"]}', '"B"', '75 is below 90 but at least 60, so the second condition prints B.', 5, 3, true, '2026-11-15 23:12:41.844027+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (34, 4, 'Beginner', 'code_output', 'What does this switch statement print?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    char choice = ''b'';\n    switch (choice) {\n        case ''a'': cout << \"Alpha\"; break;\n        case ''b'': cout << \"Beta\"; break;\n        default: cout << \"Other\";\n    }\n    return 0;\n}", "options": ["Alpha", "Beta", "Other", "b"]}', '"Beta"', 'choice is b, so the matching case prints Beta.', 5, 4, true, '2026-11-15 23:12:41.844027+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (35, 4, 'Intermediate', 'code_output', 'Which letter does the nested condition print?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int number = 12;\n    if (number > 10) {\n        if (number % 3 == 0) cout << \"A\";\n        else cout << \"B\";\n    } else cout << \"C\";\n    return 0;\n}", "options": ["A", "B", "C", "No output"]}', '"A"', '12 is greater than 10 and divisible by 3, so the inner if prints A.', 10, 5, true, '2026-11-16 13:33:38.451108+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (36, 4, 'Intermediate', 'code_output', 'What does this condition print?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int x = 2, y = 4;\n    if (x++ > 2 || ++y > 4) cout << x << \" \" << y << \" T\";\n    else cout << x << \" \" << y << \" F\";\n    return 0;\n}", "options": ["3 5 T", "3 4 F", "2 5 T", "3 5 F"]}', '"3 5 T"', 'x++ compares old x=2, then x becomes 3. The left side is false, so ++y runs: y becomes 5 and the full condition is true.', 10, 6, true, '2026-11-16 13:33:38.451108+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (72, 8, 'Beginner', 'code_output', 'What does this string concatenation print?', '{"code": "#include <iostream>\n#include <string>\nusing namespace std;\nint main() {\n    string first = \"Pro\";\n    string second = \"DSA\";\n    cout << first + second;\n    return 0;\n}", "options": ["Pro DSA", "ProDSA", "DSAPro", "Compilation error"]}', '"ProDSA"', 'The + operator joins the two strings directly.', 5, 3, true, '2026-11-16 13:43:40.451747+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (37, 4, 'Advanced', 'code_output', 'Which letter does this combined condition print?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int a = 4, b = 7;\n    if (a > 3 && b < 5 || b == 7) cout << \"X\";\n    else cout << \"Y\";\n    return 0;\n}", "options": ["X", "Y", "Both X and Y", "No output"]}', '"X"', '&& is evaluated before ||. The left side is false, but b == 7 is true, so the whole condition is true.', 15, 7, true, '2026-11-16 13:35:43.017562+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (38, 4, 'Advanced', 'code_output', 'What does the program print? Track which side of || runs.', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int x = 1, y = 2;\n    if (x++ == 1 || ++y == 3) cout << x << \" \" << y << \" Yes\";\n    else cout << x << \" \" << y << \" No\";\n    return 0;\n}", "options": ["2 2 Yes", "2 3 Yes", "1 3 Yes", "2 2 No"]}', '"2 2 Yes"', 'x++ compares 1 and makes x become 2. The left side is true, so || skips the right side and y stays 2.', 15, 8, true, '2026-11-16 13:35:43.017562+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (39, 4, 'Advanced', 'code_output', 'Which state does the nested conditional operator choose for temperature 15?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int temperature = 15;\n    const char* state = temperature > 25 ? \"Hot\"\n        : temperature > 10 ? \"Warm\" : \"Cold\";\n    cout << state;\n    return 0;\n}", "options": ["Hot", "Warm", "Cold", "Compilation error"]}', '"Warm"', '15 is not greater than 25, but it is greater than 10, so the second condition selects Warm.', 15, 9, true, '2026-11-16 13:35:43.017562+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (40, 5, 'Beginner', 'code_output', 'What does this for loop print?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    for (int i = 1; i <= 3; i++) cout << i;\n    return 0;\n}", "options": ["123", "6", "012", "321"]}', '"123"', 'The loop prints 1, then 2, then 3.', 5, 1, true, '2026-11-16 13:36:22.795219+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (41, 5, 'Beginner', 'code_output', 'What does this while loop print?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int count = 3;\n    while (count > 0) {\n        cout << count;\n        count--;\n    }\n    return 0;\n}", "options": ["123", "321", "333", "0"]}', '"321"', 'count starts at 3 and decreases after each print, so the output is 321.', 5, 2, true, '2026-11-16 13:36:22.795219+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (42, 5, 'Beginner', 'code_output', 'How many times does this do-while loop print?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int i = 5;\n    do {\n        cout << i;\n        i++;\n    } while (i < 5);\n    return 0;\n}", "options": ["0 times", "1 time", "5 times", "It runs forever"]}', '"1 time"', 'A do-while loop runs its body once before checking the condition.', 5, 3, true, '2026-11-16 13:36:22.795219+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (43, 5, 'Beginner', 'code_output', 'What does this loop print before break stops it?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    for (int i = 1; i <= 5; i++) {\n        if (i == 4) break;\n        cout << i;\n    }\n    return 0;\n}", "options": ["123", "1234", "12345", "4"]}', '"123"', 'When i becomes 4, break exits the loop before cout runs for that iteration.', 5, 4, true, '2026-11-16 13:36:22.795219+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (44, 5, 'Intermediate', 'code_output', 'How many times does the inner loop run in total?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int count = 0;\n    for (int i = 1; i <= 3; i++) {\n        for (int j = 1; j <= i; j++) count++;\n    }\n    cout << count;\n    return 0;\n}", "options": ["3", "5", "6", "9"]}', '"6"', 'The inner loop runs 1 time for i=1, 2 times for i=2, and 3 times for i=3. Total: 6.', 10, 5, true, '2026-11-16 13:37:06.319632+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (45, 5, 'Intermediate', 'code_output', 'What value does sum contain after the loop?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int sum = 0;\n    for (int i = 1; i <= 5; i++) {\n        if (i == 3) continue;\n        sum += i;\n    }\n    cout << sum;\n    return 0;\n}", "options": ["9", "12", "15", "8"]}', '"12"', 'continue skips 3, so sum is 1 + 2 + 4 + 5 = 12.', 10, 6, true, '2026-11-16 13:37:06.319632+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (46, 5, 'Intermediate', 'code_output', 'What value does this do-while loop print?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int value = 1;\n    do {\n        value *= 2;\n    } while (value < 10);\n    cout << value;\n    return 0;\n}", "options": ["8", "10", "16", "32"]}', '"16"', 'value doubles to 2, 4, 8, then 16. At 16, value < 10 is false.', 10, 7, true, '2026-11-16 13:37:06.319632+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (47, 5, 'Advanced', 'code_output', 'How many times does count increase before the loops finish?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int count = 0;\n    for (int i = 1; i <= 3; i++) {\n        for (int j = 1; j <= 3; j++) {\n            if (i + j == 4) break;\n            count++;\n        }\n    }\n    cout << count;\n    return 0;\n}", "options": ["2", "3", "4", "6"]}', '"3"', 'For i=1, count increases twice; for i=2, once; for i=3, zero times. Total: 3.', 15, 8, true, '2026-11-16 13:37:53.218968+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (48, 5, 'Advanced', 'code_output', 'What value does total contain after the loop?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int total = 0;\n    for (int i = 0; i < 6; i++) {\n        if (i % 2 == 0) continue;\n        total += i * 2;\n    }\n    cout << total;\n    return 0;\n}", "options": ["12", "18", "24", "30"]}', '"18"', 'continue skips even i values. The loop adds 1×2 + 3×2 + 5×2 = 18.', 15, 9, true, '2026-11-16 13:37:53.218968+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (49, 5, 'Advanced', 'code_output', 'What value is printed after both loops finish?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int i = 0;\n    while (i < 3) {\n        for (int j = 0; j < 2; j++) i++;\n    }\n    cout << i;\n    return 0;\n}", "options": ["2", "3", "4", "5"]}', '"4"', 'The inner loop adds 2 to i each time. The outer loop runs with i=0 and i=2, leaving i=4.', 15, 10, true, '2026-11-16 13:37:53.218968+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (50, 6, 'Beginner', 'code_output', 'What does the program print when greet() is called?', '{"code": "#include <iostream>\nusing namespace std;\nvoid greet() {\n    cout << \"Hello\";\n}\nint main() {\n    greet();\n    return 0;\n}", "options": ["Hello", "greet", "main", "No output"]}', '"Hello"', 'main calls greet(), and greet prints Hello.', 5, 1, true, '2026-11-16 13:39:01.726994+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (51, 6, 'Beginner', 'code_output', 'What value does add(3, 4) return?', '{"code": "#include <iostream>\nusing namespace std;\nint add(int a, int b) {\n    return a + b;\n}\nint main() {\n    cout << add(3, 4);\n    return 0;\n}", "options": ["1", "7", "12", "34"]}', '"7"', 'The function returns the sum of its arguments: 3 + 4 = 7.', 5, 2, true, '2026-11-16 13:39:01.726994+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (52, 6, 'Beginner', 'code_output', 'What does this program print?', '{"code": "#include <iostream>\nusing namespace std;\nvoid mark() {\n    cout << \"*\";\n}\nint main() {\n    mark();\n    mark();\n    mark();\n    return 0;\n}", "options": ["*", "**", "***", "3"]}', '"***"', 'Each call to mark() prints one asterisk. The function is called three times.', 5, 3, true, '2026-11-16 13:39:01.726994+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (53, 6, 'Beginner', 'code_output', 'What value does the program print?', '{"code": "#include <iostream>\nusing namespace std;\nint increase(int n) {\n    return n + 2;\n}\nint main() {\n    cout << increase(3) * 2;\n    return 0;\n}", "options": ["5", "6", "10", "12"]}', '"10"', 'increase(3) returns 5, and 5 multiplied by 2 is 10.', 5, 4, true, '2026-11-16 13:39:01.726994+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (54, 6, 'Intermediate', 'code_output', 'What value is printed after change(value) returns?', '{"code": "#include <iostream>\nusing namespace std;\nvoid change(int x) {\n    x *= 2;\n}\nint main() {\n    int value = 6;\n    change(value);\n    cout << value;\n    return 0;\n}", "options": ["6", "12", "0", "Compilation error"]}', '"6"', 'The function receives a copy of value. Changing x does not change the original variable.', 10, 5, true, '2026-11-16 13:39:38.564546+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (55, 6, 'Intermediate', 'code_output', 'What does calculate(7) return?', '{"code": "#include <iostream>\nusing namespace std;\nint calculate(int n) {\n    if (n % 2 == 0) return n / 2;\n    return n * 3 + 1;\n}\nint main() {\n    cout << calculate(7);\n    return 0;\n}", "options": ["10", "21", "22", "28"]}', '"22"', '7 is odd, so the function returns 7 × 3 + 1, which is 22.', 10, 6, true, '2026-11-16 13:39:38.564546+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (56, 6, 'Intermediate', 'code_output', 'What value is printed by the nested function calls?', '{"code": "#include <iostream>\nusing namespace std;\nint multiply(int a, int b) {\n    return a * b;\n}\nint add(int a, int b) {\n    return a + b;\n}\nint main() {\n    cout << add(multiply(2, 3), multiply(1, 4));\n    return 0;\n}", "options": ["10", "14", "24", "36"]}', '"10"', 'The multiply calls return 6 and 4. Then add(6, 4) returns 10.', 10, 7, true, '2026-11-16 13:39:38.564546+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (57, 6, 'Advanced', 'code_output', 'What value is printed after the reference parameter is changed?', '{"code": "#include <iostream>\nusing namespace std;\nvoid update(int& score, int bonus) {\n    score += bonus;\n}\nint main() {\n    int score = 10;\n    update(score, 5);\n    cout << score;\n    return 0;\n}", "options": ["10", "15", "5", "Compilation error"]}', '"15"', 'score is passed by reference, so adding bonus changes the original variable from 10 to 15.', 15, 8, true, '2026-11-16 13:40:21.450447+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (58, 6, 'Advanced', 'code_output', 'What does the recursive function sumTo(5) return?', '{"code": "#include <iostream>\nusing namespace std;\nint sumTo(int n) {\n    if (n == 0) return 0;\n    return n + sumTo(n - 1);\n}\nint main() {\n    cout << sumTo(5);\n    return 0;\n}", "options": ["10", "15", "20", "120"]}', '"15"', 'The function returns 5 + 4 + 3 + 2 + 1 + 0, which equals 15.', 15, 9, true, '2026-11-16 13:40:21.450447+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (59, 6, 'Advanced', 'code_output', 'What value is printed after the overloaded function calls?', '{"code": "#include <iostream>\nusing namespace std;\nint combine(int x) {\n    return x + 2;\n}\nint combine(int x, int y) {\n    return x * y;\n}\nint main() {\n    cout << combine(combine(3), 4);\n    return 0;\n}", "options": ["12", "20", "21", "24"]}', '"20"', 'The one-argument call returns 3 + 2 = 5. The two-argument overload then returns 5 × 4 = 20.', 15, 10, true, '2026-11-16 13:40:21.450447+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (60, 7, 'Beginner', 'code_output', 'What value is stored at index 0?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int values[3] = {4, 7, 9};\n    cout << values[0];\n    return 0;\n}", "options": ["4", "7", "9", "0"]}', '"4"', 'C++ arrays use zero-based indexing, so index 0 contains the first value, 4.', 5, 1, true, '2026-11-16 13:41:10.53265+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (61, 7, 'Beginner', 'code_output', 'What is the last valid index of this array?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int values[4] = {2, 5, 8, 11};\n    cout << 3;\n    return 0;\n}", "options": ["2", "3", "4", "5"]}', '"3"', 'An array of 4 elements has indices 0, 1, 2, and 3.', 5, 2, true, '2026-11-16 13:41:10.53265+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (62, 7, 'Beginner', 'code_output', 'What value is printed after the array element is changed?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int values[3] = {1, 2, 3};\n    values[1] = 10;\n    cout << values[1];\n    return 0;\n}", "options": ["1", "2", "3", "10"]}', '"10"', 'Index 1 is updated from 2 to 10, and that value is printed.', 5, 3, true, '2026-11-16 13:41:10.53265+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (63, 7, 'Beginner', 'code_output', 'What sum does the loop calculate?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int values[3] = {2, 3, 4};\n    int sum = 0;\n    for (int i = 0; i < 3; i++) sum += values[i];\n    cout << sum;\n    return 0;\n}", "options": ["7", "8", "9", "10"]}', '"9"', 'The loop adds all three values: 2 + 3 + 4 = 9.', 5, 4, true, '2026-11-16 13:41:10.53265+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (64, 7, 'Intermediate', 'code_output', 'What value is stored in result?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int values[4] = {3, 6, 9, 12};\n    int result = values[0] + values[2] - values[1];\n    cout << result;\n    return 0;\n}", "options": ["3", "6", "9", "12"]}', '"6"', 'The expression is values[0] + values[2] - values[1], or 3 + 9 - 6 = 6.', 10, 5, true, '2026-11-16 13:41:47.798011+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (65, 7, 'Intermediate', 'code_output', 'What sequence does this loop print?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int values[4] = {1, 2, 3, 4};\n    for (int i = 3; i >= 1; i--) cout << values[i];\n    return 0;\n}", "options": ["432", "4321", "123", "321"]}', '"432"', 'The loop visits indices 3, 2, and 1, printing 4, 3, and 2.', 10, 6, true, '2026-11-16 13:41:47.798011+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (66, 7, 'Intermediate', 'code_output', 'How many array values are greater than 5?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int values[5] = {4, 7, 2, 7, 9};\n    int count = 0;\n    for (int i = 0; i < 5; i++) {\n        if (values[i] > 5) count++;\n    }\n    cout << count;\n    return 0;\n}", "options": ["1", "2", "3", "4"]}', '"3"', 'The values greater than 5 are 7, 7, and 9, so count is 3.', 10, 7, true, '2026-11-16 13:41:47.798011+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (67, 7, 'Advanced', 'code_output', 'What value is stored at index 2 after the prefix-sum loop?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int values[4] = {2, 4, 6, 8};\n    for (int i = 1; i < 4; i++) values[i] += values[i - 1];\n    cout << values[2];\n    return 0;\n}", "options": ["6", "10", "12", "20"]}', '"12"', 'The array becomes {2, 6, 12, 20}. Index 2 stores 12.', 15, 8, true, '2026-11-16 13:43:05.867565+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (68, 7, 'Advanced', 'code_output', 'How many matching pairs does the nested loop count?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int values[4] = {1, 2, 1, 3};\n    int pairs = 0;\n    for (int i = 0; i < 4; i++) {\n        for (int j = i + 1; j < 4; j++) {\n            if (values[i] == values[j]) pairs++;\n        }\n    }\n    cout << pairs;\n    return 0;\n}", "options": ["0", "1", "2", "3"]}', '"1"', 'Only the two values 1 match, creating one pair.', 15, 9, true, '2026-11-16 13:43:05.867565+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (69, 7, 'Advanced', 'code_output', 'What value does the pointer expression calculate?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int values[4] = {10, 20, 30, 40};\n    int* pointer = values;\n    cout << *(pointer + 2) + values[1];\n    return 0;\n}", "options": ["30", "40", "50", "60"]}', '"50"', 'pointer + 2 points to values[2], which is 30. values[1] is 20, so the sum is 50.', 15, 10, true, '2026-11-16 13:43:05.867565+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (70, 8, 'Beginner', 'code_output', 'What length does this string have?', '{"code": "#include <iostream>\n#include <string>\nusing namespace std;\nint main() {\n    string word = \"code\";\n    cout << word.length();\n    return 0;\n}", "options": ["3", "4", "5", "0"]}', '"4"', 'The string code contains four characters.', 5, 1, true, '2026-11-16 13:43:40.451747+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (71, 8, 'Beginner', 'code_output', 'Which character is printed from index 1?', '{"code": "#include <iostream>\n#include <string>\nusing namespace std;\nint main() {\n    string word = \"game\";\n    cout << word[1];\n    return 0;\n}", "options": ["g", "a", "m", "e"]}', '"a"', 'String indexing starts at 0: g is at index 0 and a is at index 1.', 5, 2, true, '2026-11-16 13:43:40.451747+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (73, 8, 'Beginner', 'code_output', 'What character does the program print?', '{"code": "#include <iostream>\n#include <string>\nusing namespace std;\nint main() {\n    string name = \"Ada\";\n    cout << name[2];\n    return 0;\n}", "options": ["A", "d", "a", "2"]}', '"a"', 'The characters are at indices 0, 1, and 2. Index 2 contains a.', 5, 4, true, '2026-11-16 13:43:40.451747+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (74, 8, 'Intermediate', 'code_output', 'What substring does this program print?', '{"code": "#include <iostream>\n#include <string>\nusing namespace std;\nint main() {\n    string text = \"adventure\";\n    cout << text.substr(2, 3);\n    return 0;\n}", "options": ["adv", "ven", "vent", "ture"]}', '"ven"', 'substr(2, 3) starts at index 2 and takes 3 characters: v, e, n.', 10, 5, true, '2026-11-16 13:44:14.337419+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (75, 8, 'Intermediate', 'code_output', 'What position does find return for v?', '{"code": "#include <iostream>\n#include <string>\nusing namespace std;\nint main() {\n    string word = \"level\";\n    cout << word.find(\"v\");\n    return 0;\n}", "options": ["1", "2", "3", "4"]}', '"2"', 'find returns the zero-based position. In level, v is at index 2.', 10, 6, true, '2026-11-16 13:44:14.337419+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (76, 8, 'Intermediate', 'code_output', 'What does the string contain after replace runs?', '{"code": "#include <iostream>\n#include <string>\nusing namespace std;\nint main() {\n    string text = \"game\";\n    text.replace(1, 2, \"XY\");\n    cout << text;\n    return 0;\n}", "options": ["gXYe", "XYme", "gaXY", "gXYme"]}', '"gXYe"', 'replace(1, 2, "XY") replaces two characters starting at index 1.', 10, 7, true, '2026-11-16 13:44:14.337419+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (77, 8, 'Advanced', 'code_output', 'What string is printed after erase and insert?', '{"code": "#include <iostream>\n#include <string>\nusing namespace std;\nint main() {\n    string text = \"abcdef\";\n    text.erase(2, 2);\n    text.insert(2, \"XY\");\n    cout << text;\n    return 0;\n}", "options": ["abXYef", "aXYdef", "abefXY", "abcdef"]}', '"abXYef"', 'erase removes c and d, leaving abef. insert(2, "XY") places XY after ab.', 15, 8, true, '2026-11-16 13:44:55.639367+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (78, 8, 'Advanced', 'code_output', 'What positions do find and rfind print for na?', '{"code": "#include <iostream>\n#include <string>\nusing namespace std;\nint main() {\n    string text = \"banana\";\n    cout << text.find(\"na\") << \" \" << text.rfind(\"na\");\n    return 0;\n}", "options": ["1 3", "2 4", "2 2", "4 2"]}', '"2 4"', 'The first na starts at index 2, and the last na starts at index 4.', 15, 9, true, '2026-11-16 13:44:55.639367+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (79, 8, 'Advanced', 'code_output', 'Which word is printed by this string comparison?', '{"code": "#include <iostream>\n#include <string>\nusing namespace std;\nint main() {\n    string first = \"apple\";\n    string second = \"apply\";\n    if (first < second) cout << \"First\";\n    else cout << \"Second\";\n    return 0;\n}", "options": ["First", "Second", "apple", "Compilation error"]}', '"First"', 'The strings match through appl. At the next character, e comes before y.', 15, 10, true, '2026-11-16 13:44:55.639367+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (80, 9, 'Beginner', 'code_output', 'What value does this pointer program print?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int value = 10;\n    int* pointer = &value;\n    cout << *pointer;\n    return 0;\n}", "options": ["0", "10", "The address", "Compilation error"]}', '"10"', 'pointer stores the address of value. *pointer reads the value at that address.', 5, 1, true, '2026-11-16 13:46:19.724291+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (81, 9, 'Beginner', 'code_output', 'What value does value contain after the pointer assignment?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int value = 5;\n    int* pointer = &value;\n    *pointer = 7;\n    cout << value;\n    return 0;\n}", "options": ["5", "7", "12", "The address"]}', '"7"', '*pointer refers to value, so assigning 7 through the pointer changes value to 7.', 5, 2, true, '2026-11-16 13:46:19.724291+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (82, 9, 'Beginner', 'code_output', 'What does this null-pointer check print?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int* pointer = nullptr;\n    cout << (pointer == nullptr);\n    return 0;\n}", "options": ["0", "1", "nullptr", "Compilation error"]}', '"1"', 'pointer is nullptr, so the comparison is true. C++ prints true as 1 by default.', 5, 3, true, '2026-11-16 13:46:19.724291+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (83, 9, 'Beginner', 'code_output', 'What does this address comparison print?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int number = 8;\n    int* pointer = &number;\n    cout << (pointer == &number);\n    return 0;\n}", "options": ["0", "1", "8", "The address"]}', '"1"', 'pointer was set to the address of number, so both sides refer to the same address.', 5, 4, true, '2026-11-16 13:46:19.724291+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (84, 9, 'Intermediate', 'code_output', 'What value is printed after the pointer moves forward once?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int values[3] = {10, 20, 30};\n    int* pointer = values;\n    pointer++;\n    cout << *pointer;\n    return 0;\n}", "options": ["10", "20", "30", "The address"]}', '"20"', 'The pointer starts at values[0]. Incrementing it once moves it to values[1], which is 20.', 10, 5, true, '2026-11-16 13:46:56.584786+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (85, 9, 'Intermediate', 'code_output', 'What value does the pointer arithmetic expression calculate?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int values[4] = {5, 10, 15, 20};\n    int* pointer = values;\n    cout << *(pointer + 2) - *pointer;\n    return 0;\n}", "options": ["5", "10", "15", "20"]}', '"10"', '*(pointer + 2) is values[2], which is 15. *pointer is values[0], which is 5. The difference is 10.', 10, 6, true, '2026-11-16 13:46:56.584786+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (86, 9, 'Intermediate', 'code_output', 'What value does the pointer-to-pointer expression print?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int value = 9;\n    int* pointer = &value;\n    int** pointerToPointer = &pointer;\n    cout << **pointerToPointer;\n    return 0;\n}", "options": ["0", "9", "The address", "Compilation error"]}', '"9"', 'The first * reaches pointer. The second * reaches the integer value 9.', 10, 7, true, '2026-11-16 13:46:56.584786+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (87, 9, 'Advanced', 'code_output', 'What is the difference between these two array pointers?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int values[5] = {2, 4, 6, 8, 10};\n    int* first = &values[1];\n    int* last = &values[4];\n    cout << last - first;\n    return 0;\n}", "options": ["2", "3", "4", "12"]}', '"3"', 'Pointer subtraction gives the number of elements between the positions: index 4 - index 1 = 3.', 15, 8, true, '2026-11-16 13:47:31.143626+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (88, 9, 'Advanced', 'code_output', 'What value is printed after changing the integer through pointerToPointer?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int value = 4;\n    int* pointer = &value;\n    int** pointerToPointer = &pointer;\n    **pointerToPointer += 3;\n    cout << value;\n    return 0;\n}", "options": ["4", "7", "12", "Compilation error"]}', '"7"', 'Dereferencing twice reaches value. Adding 3 changes the original value from 4 to 7.', 15, 9, true, '2026-11-16 13:47:31.143626+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (89, 9, 'Advanced', 'code_output', 'What value is printed after advance moves the pointer?', '{"code": "#include <iostream>\nusing namespace std;\nvoid advance(int*& pointer) {\n    pointer++;\n}\nint main() {\n    int values[3] = {2, 4, 6};\n    int* pointer = values;\n    advance(pointer);\n    cout << *pointer;\n    return 0;\n}", "options": ["2", "4", "6", "The address"]}', '"4"', 'int*& lets advance change the caller’s pointer. It moves from values[0] to values[1], which is 4.', 15, 10, true, '2026-11-16 13:47:31.143626+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (90, 10, 'Beginner', 'code_output', 'What does this object program print?', '{"code": "#include <iostream>\nusing namespace std;\nclass Player {\npublic:\n    int score;\n};\nint main() {\n    Player hero;\n    hero.score = 10;\n    cout << hero.score;\n    return 0;\n}", "options": ["0", "10", "score", "Compilation error"]}', '"10"', 'hero is an object of Player. Its score member is set to 10 and then printed.', 5, 1, true, '2026-11-16 13:48:11.82882+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (91, 10, 'Beginner', 'code_output', 'What does the greet member function print?', '{"code": "#include <iostream>\nusing namespace std;\nclass Greeter {\npublic:\n    void greet() {\n        cout << \"Hi\";\n    }\n};\nint main() {\n    Greeter person;\n    person.greet();\n    return 0;\n}", "options": ["Greeter", "greet", "Hi", "No output"]}', '"Hi"', 'person.greet() calls the member function, which prints Hi.', 5, 2, true, '2026-11-16 13:48:11.82882+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (92, 10, 'Beginner', 'code_output', 'How many does the counter print after two calls to increase()?', '{"code": "#include <iostream>\nusing namespace std;\nclass Counter {\npublic:\n    int value = 0;\n    void increase() {\n        value++;\n    }\n};\nint main() {\n    Counter counter;\n    counter.increase();\n    counter.increase();\n    cout << counter.value;\n    return 0;\n}", "options": ["0", "1", "2", "3"]}', '"2"', 'Each call increases value by 1. Two calls make it 2.', 5, 3, true, '2026-11-16 13:48:11.82882+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (93, 10, 'Beginner', 'code_output', 'What name does the constructor assign to the player?', '{"code": "#include <iostream>\n#include <string>\nusing namespace std;\nclass Player {\npublic:\n    string name;\n    Player() {\n        name = \"Riya\";\n    }\n};\nint main() {\n    Player hero;\n    cout << hero.name;\n    return 0;\n}", "options": ["Player", "hero", "Riya", "No name"]}', '"Riya"', 'The constructor runs when hero is created and assigns Riya to name.', 5, 4, true, '2026-11-16 13:48:11.82882+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (94, 10, 'Intermediate', 'code_output', 'What value does the Box object return?', '{"code": "#include <iostream>\nusing namespace std;\nclass Box {\nprivate:\n    int width;\npublic:\n    Box(int w) : width(w) {}\n    int getWidth() { return width; }\n};\nint main() {\n    Box box(7);\n    cout << box.getWidth();\n    return 0;\n}", "options": ["0", "1", "7", "Compilation error"]}', '"7"', 'The constructor stores 7 in width, and getWidth() returns it.', 10, 5, true, '2026-11-16 13:48:51.310306+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (95, 10, 'Intermediate', 'code_output', 'What values do the two independent Counter objects print?', '{"code": "#include <iostream>\nusing namespace std;\nclass Counter {\npublic:\n    int value;\n};\nint main() {\n    Counter first{2};\n    Counter second{5};\n    first.value += 3;\n    cout << first.value << \" \" << second.value;\n    return 0;\n}", "options": ["5 5", "2 8", "5 8", "8 5"]}', '"5 5"', 'Changing first.value does not change second.value. The objects hold separate values.', 10, 6, true, '2026-11-16 13:48:51.310306+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (96, 10, 'Intermediate', 'code_output', 'What value does the Meter object hold after both scale calls?', '{"code": "#include <iostream>\nusing namespace std;\nclass Meter {\npublic:\n    int value = 1;\n    void scale(int factor) {\n        value *= factor;\n    }\n};\nint main() {\n    Meter meter;\n    meter.scale(3);\n    meter.scale(2);\n    cout << meter.value;\n    return 0;\n}", "options": ["3", "5", "6", "7"]}', '"6"', 'value starts at 1, then becomes 1 × 3 = 3, then 3 × 2 = 6.', 10, 7, true, '2026-11-16 13:48:51.310306+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (97, 10, 'Advanced', 'code_output', 'What does the virtual function call print?', '{"code": "#include <iostream>\nusing namespace std;\nclass Base {\npublic:\n    virtual void show() { cout << \"Base\"; }\n};\nclass Derived : public Base {\npublic:\n    void show() override { cout << \"Derived\"; }\n};\nint main() {\n    Derived object;\n    Base* pointer = &object;\n    pointer->show();\n    return 0;\n}", "options": ["Base", "Derived", "BaseDerived", "Compilation error"]}', '"Derived"', 'Because show() is virtual, the call uses the actual object type, Derived.', 15, 8, true, '2026-11-16 13:49:29.43286+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (98, 10, 'Advanced', 'code_output', 'What does this non-virtual function call print?', '{"code": "#include <iostream>\nusing namespace std;\nclass Base {\npublic:\n    void show() { cout << \"Base\"; }\n};\nclass Derived : public Base {\npublic:\n    void show() { cout << \"Derived\"; }\n};\nint main() {\n    Derived object;\n    Base* pointer = &object;\n    pointer->show();\n    return 0;\n}", "options": ["Base", "Derived", "BaseDerived", "Compilation error"]}', '"Base"', 'show() is not virtual, so the call through a Base pointer uses Base::show().', 15, 9, true, '2026-11-16 13:49:29.43286+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (99, 10, 'Advanced', 'code_output', 'In what order do the constructors print their letters?', '{"code": "#include <iostream>\nusing namespace std;\nclass Base {\npublic:\n    Base() { cout << \"B\"; }\n};\nclass Derived : public Base {\npublic:\n    Derived() { cout << \"D\"; }\n};\nint main() {\n    Derived object;\n    return 0;\n}", "options": ["B", "D", "BD", "DB"]}', '"BD"', 'The base-class constructor runs first, followed by the derived-class constructor.', 15, 10, true, '2026-11-16 13:49:29.43286+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (100, 11, 'Beginner', 'code_output', 'What size does the vector have after push_back?', '{"code": "#include <iostream>\n#include <vector>\nusing namespace std;\nint main() {\n    vector<int> values = {3, 6};\n    values.push_back(9);\n    cout << values.size();\n    return 0;\n}", "options": ["2", "3", "6", "9"]}', '"3"', 'The vector starts with two elements. push_back adds one more, so its size becomes 3.', 5, 1, true, '2026-11-16 13:50:13.987954+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (101, 11, 'Beginner', 'code_output', 'What value does this vector access print?', '{"code": "#include <iostream>\n#include <vector>\nusing namespace std;\nint main() {\n    vector<int> values = {4, 8, 12};\n    cout << values.at(1);\n    return 0;\n}", "options": ["4", "8", "12", "1"]}', '"8"', 'Vector indexing starts at 0, so index 1 contains the second value, 8.', 5, 2, true, '2026-11-16 13:50:13.987954+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (102, 11, 'Beginner', 'code_output', 'What value is printed from the vector initialized with a size and value?', '{"code": "#include <iostream>\n#include <vector>\nusing namespace std;\nint main() {\n    vector<int> values(3, 2);\n    cout << values[2];\n    return 0;\n}", "options": ["0", "2", "3", "6"]}', '"2"', 'vector<int>(3, 2) creates three elements, each initialized to 2.', 5, 3, true, '2026-11-16 13:50:13.987954+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (103, 11, 'Beginner', 'code_output', 'What does this pair program print?', '{"code": "#include <iostream>\n#include <string>\n#include <utility>\nusing namespace std;\nint main() {\n    pair<string, int> player = {\"Ava\", 5};\n    cout << player.first;\n    return 0;\n}", "options": ["Ava", "5", "first", "Compilation error"]}', '"Ava"', 'A pair stores two values. first accesses the string value, Ava.', 5, 4, true, '2026-11-16 13:50:13.987954+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (104, 11, 'Intermediate', 'code_output', 'What value is at index 1 after erase removes the second element?', '{"code": "#include <iostream>\n#include <vector>\nusing namespace std;\nint main() {\n    vector<int> values = {2, 4, 6, 8};\n    values.erase(values.begin() + 1);\n    cout << values[1];\n    return 0;\n}", "options": ["2", "4", "6", "8"]}', '"6"', 'After removing 4, the vector is {2, 6, 8}. Index 1 contains 6.', 10, 5, true, '2026-11-16 13:50:54.246015+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (105, 11, 'Intermediate', 'code_output', 'What value is at the middle index after sorting?', '{"code": "#include <algorithm>\n#include <iostream>\n#include <vector>\nusing namespace std;\nint main() {\n    vector<int> values = {4, 1, 3};\n    sort(values.begin(), values.end());\n    cout << values[1];\n    return 0;\n}", "options": ["1", "3", "4", "1 3 4"]}', '"3"', 'After sorting, the vector is {1, 3, 4}. Index 1 contains 3.', 10, 6, true, '2026-11-16 13:50:54.246015+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (106, 11, 'Intermediate', 'code_output', 'What value is stored for Ava in the map?', '{"code": "#include <iostream>\n#include <map>\n#include <string>\nusing namespace std;\nint main() {\n    map<string, int> scores;\n    scores[\"Ava\"] = 2;\n    scores[\"Ava\"] += 3;\n    cout << scores[\"Ava\"];\n    return 0;\n}", "options": ["2", "3", "5", "Ava"]}', '"5"', 'Ava starts with 2 points, then 3 is added, so the stored value is 5.', 10, 7, true, '2026-11-16 13:50:54.246015+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (107, 11, 'Advanced', 'code_output', 'What size does the vector have after removing adjacent duplicates?', '{"code": "#include <algorithm>\n#include <iostream>\n#include <vector>\nusing namespace std;\nint main() {\n    vector<int> values = {1, 2, 2, 3};\n    values.erase(unique(values.begin(), values.end()), values.end());\n    cout << values.size();\n    return 0;\n}", "options": ["2", "3", "4", "5"]}', '"3"', 'unique moves duplicate values to the end. erase removes that tail, leaving {1, 2, 3}.', 15, 8, true, '2026-11-16 13:51:33.887485+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (108, 11, 'Advanced', 'code_output', 'In what order does this map print its values?', '{"code": "#include <iostream>\n#include <map>\nusing namespace std;\nint main() {\n    map<int, char> letters;\n    letters[3] = ''C'';\n    letters[1] = ''A'';\n    letters[2] = ''B'';\n    for (auto it = letters.begin(); it != letters.end(); ++it)\n        cout << it->second;\n    return 0;\n}", "options": ["CBA", "ABC", "BAC", "ACB"]}', '"ABC"', 'map iterates in ascending key order: 1, 2, 3, so the values print A, B, C.', 15, 9, true, '2026-11-16 13:51:33.887485+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (109, 11, 'Advanced', 'code_output', 'What index and value does lower_bound find for 4?', '{"code": "#include <algorithm>\n#include <iostream>\n#include <vector>\nusing namespace std;\nint main() {\n    vector<int> values = {1, 3, 5, 7};\n    auto it = lower_bound(values.begin(), values.end(), 4);\n    cout << (it - values.begin()) << \" \" << *it;\n    return 0;\n}", "options": ["1 3", "2 5", "2 4", "3 7"]}', '"2 5"', 'lower_bound returns the first element not less than 4: value 5 at index 2.', 15, 10, true, '2026-11-16 13:51:33.887485+05:30');
INSERT INTO public.training_questions (id, topic_id, difficulty, question_type, prompt, content, correct_answer, explanation, xp_reward, display_order, is_active, created_at) VALUES (110, 4, 'Intermediate', 'code_output', 'Which message is printed for score 72?', '{"code": "#include <iostream>\nusing namespace std;\nint main() {\n    int score = 72;\n    if (score >= 80) cout << \"High\";\n    else if (score >= 60) {\n        if (score % 2 == 0) cout << \"Even Pass\";\n        else cout << \"Pass\";\n    } else cout << \"Retry\";\n    return 0;\n}", "options": ["High", "Even Pass", "Pass", "Retry"]}', '"Even Pass"', '72 is at least 60 and is even, so the nested condition prints Even Pass.', 10, 10, true, '2026-11-16 13:54:17.200623+05:30');
